function SonogramResponseInset({concept,p,phase}){
 const id=concept.id,m=computeVisualMetrics(p),domain=Math.max(1000,Math.abs(m.dopplerHz)*1.5),power=retainedPowerFraction(p);
 if(inSet(id,['orientation','pressure','deep'])){const long=id==='orientation'&&p.rotation>=75,rx=id==='orientation'?22/Math.max(.28,Math.cos(p.rotation*Math.PI/180)):52,ry=id==='orientation'?17:Math.max(1.5,18*(1-p.pressure/100));return <g transform="translate(652 427)"><rect width="200" height="76" rx="6" fill="#071824" fillOpacity=".94" stroke="#395b73"/><GraphicText x="10" y="18" fill="#bdd5e3" fontSize="12">{id==='orientation'?'Plano del mismo vaso':'Misma luz durante la presión'} · esquema</GraphicText>{long?<><rect x="16" y="34" width="168" height="28" fill="#05121e"/><path d="M16 34H184M16 62H184" stroke={C.cyan} strokeWidth="2"/></>:<ellipse cx="100" cy="47" rx={rx} ry={ry} fill="#05121e" stroke={C.cyan} strokeWidth="2"/>}</g>;}
 let title='Entrada → presentación',fn=t=>transferBrightness(t,p.gain,p.dynamic);
 if(id==='colorGain'){title='Señal → color';fn=t=>transferBrightness(t,p.colorGain,p.dynamic);}
 if(id==='tgc'){title='Recepción por profundidad';fn=t=>Math.min(1,attenuationAmplitude(t*5,p.frequency)*Math.pow(10,p.tgc/100*.5*p.frequency*t*5/20));}
 if(id==='persistence'){title='Respuesta temporal';fn=t=>delayedPersistence(t*6,p.persistence);}
 if(id==='filter'){title='Señal tras el filtro';fn=t=>t*domain>p.filter?Math.exp(-Math.pow((t*domain-Math.abs(m.dopplerHz))/Math.max(25,Math.abs(m.dopplerHz)*.16),2)):0;}
 if(id==='power'){title='Potencia conservada';fn=()=>power;}
 if(id==='color'){title='Componente sobre el haz';fn=t=>.5+Math.sin(t*22-phase*6)*Math.min(.45,Math.abs(m.dopplerHz)/2000);}
 return <g transform="translate(652 427)"><rect width="200" height="76" rx="6" fill="#071824" fillOpacity=".94" stroke="#395b73"/><GraphicText x="10" y="18" fill="#bdd5e3" fontSize="12">{title} · esquema</GraphicText><path d="M10 28V65H190" stroke="#416076" fill="none"/><path d={pathFrom(fn,{x:10,y:65,width:180,height:33,n:100})} stroke={id==='power'?C.gold:C.cyan} fill="none" strokeWidth="2"/></g>;
}
